function addParticle(x,y,color,n=8,speed=130){for(let i=0;i<n;i++){const a=rand(0,Math.PI*2),v=rand(speed*.25,speed);particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:rand(.25,.65),max:.65,r:rand(1.5,3.8),color})}}
function fire(){if(player.fire>0)return;player.fire=.19;const target=drones.reduce((best,d)=>{const dist=Math.hypot(d.x-player.x,d.y-player.y);return dist<best.dist?{d,dist}:best},{dist:Infinity}).d;let a=player.angle;if(target&&stickInput.x===0&&stickInput.y===0&&!mouse.down){a=Math.atan2(target.y-player.y,target.x-player.x)}shots.push({x:player.x+Math.cos(a)*16,y:player.y+Math.sin(a)*16,vx:Math.cos(a)*520,vy:Math.sin(a)*520,life:.9});addParticle(player.x+Math.cos(a)*15,player.y+Math.sin(a)*15,'#68f2e1',3,55)}
function damage(){if(player.invuln>0)return;player.hp--;player.invuln=1.2;screenShake=10;addParticle(player.x,player.y,'#ff5d9e',18,200);drawHud();if(player.hp<=0){state='lose';setPanel('lose')}}
function update(dt){elapsed+=dt;player.fire-=dt;player.dashLock-=dt;player.dash-=dt;player.invuln-=dt;spawnTimer-=dt;
let mx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0)+stickInput.x,my=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0)+stickInput.y;let mag=Math.hypot(mx,my);if(mag>1){mx/=mag;my/=mag}
if(Math.abs(mx)+Math.abs(my)>.02)player.angle=Math.atan2(my,mx);else if(mouse.down)player.angle=Math.atan2(mouse.y-player.y,mouse.x-player.x);else if(drones.length)player.angle=Math.atan2(drones[0].y-player.y,drones[0].x-player.x);
if(keys.has('shift')&&player.dashLock<=0){player.dash=.17;player.dashLock=1.25;showToast('PHASE DASH');}
const speed=player.dash>0?620:player.speed;player.x=Math.max(26,Math.min(W-26,player.x+mx*speed*dt));player.y=Math.max(65,Math.min(H-28,player.y+my*speed*dt));
if(mouse.down||keys.has(' ')||$('#fireBtn').matches(':active'))fire();
if(spawnTimer<=0){if(drones.length<7){const side=Math.floor(rand(0,4)),p=side===0?{x:rand(25,W-25),y:58}:side===1?{x:rand(25,W-25),y:H-25}:side===2?{x:25,y:rand(70,H-25)}:{x:W-25,y:rand(70,H-25)};drones.push({...p,r:rand(12,17),hp:2,phase:rand(0,7),speed:rand(65,91),shot:rand(1,2.4)})}spawnTimer=Math.max(.65,2.5-elapsed*.012)}
for(const d of drones){d.phase+=dt;const a=Math.atan2(player.y-d.y,player.x-d.x),dist=Math.hypot(player.x-d.x,player.y-d.y);if(dist>60){d.x+=Math.cos(a)*d.speed*dt;d.y+=Math.sin(a)*d.speed*dt}d.shot-=dt;if(d.shot<=0&&dist<420){const aim=a+rand(-.08,.08);enemyShots.push({x:d.x,y:d.y,vx:Math.cos(aim)*190,vy:Math.sin(aim)*190,life:3});d.shot=rand(2,3.2)}if(dist<d.r+player.r)damage()}
for(const s of shots){s.x+=s.vx*dt;s.y+=s.vy*dt;s.life-=dt;for(const d of drones){if(d.hp>0&&Math.hypot(s.x-d.x,s.y-d.y)<d.r+4){d.hp--;s.life=0;addParticle(s.x,s.y,'#68f2e1',5,85);if(d.hp<=0){score++;addParticle(d.x,d.y,'#ff5d9e',12,130)}}}}
drones=drones.filter(d=>d.hp>0);shots=shots.filter(s=>s.life>0&&s.x>-10&&s.x<W+10&&s.y>50&&s.y<H+10);
for(const s of enemyShots){s.x+=s.vx*dt;s.y+=s.vy*dt;s.life-=dt;if(Math.hypot(s.x-player.x,s.y-player.y)<player.r+5){s.life=0;damage()}}enemyShots=enemyShots.filter(s=>s.life>0&&s.x>-10&&s.x<W+10&&s.y>50&&s.y<H+10);
for(const c of cores){c.phase+=dt;if(Math.hypot(c.x-player.x,c.y-player.y)<c.r+player.r+6){c.taken=true;addParticle(c.x,c.y,'#68f2e1',20,180);showToast('SIGNAL CORE RECOVERED');}}const before=cores.length;cores=cores.filter(c=>!c.taken);if(before!==cores.length){drawHud();if(!cores.length){gate.open=true;showToast('GATE ONLINE — GET TO EXTRACTION')}}
if(gate.open&&Math.hypot(player.x-gate.x,player.y-gate.y)<gate.r+player.r){state='win';setPanel('win')}
for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.05,dt);p.vy*=Math.pow(.05,dt);p.life-=dt}particles=particles.filter(p=>p.life>0);screenShake=Math.max(0,screenShake-dt*28);if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('#toast').style.opacity=0}
}
function draw(){const sx=rand(-screenShake,screenShake),sy=rand(-screenShake,screenShake);ctx.save();ctx.translate(sx,sy);ctx.clearRect(-20,-20,W+40,H+40);ctx.fillStyle='#080d19';ctx.fillRect(-20,-20,W+40,H+40);
const grad=ctx.createRadialGradient(W/2,H/2,30,W/2,H/2,560);grad.addColorStop(0,'#111a2b');grad.addColorStop(1,'#080d19');ctx.fillStyle=grad;ctx.fillRect(0,0,W,H);
for(const s of stars){ctx.globalAlpha=s.a*(.72+.28*Math.sin(elapsed*1.3+s.phase));ctx.fillStyle='#c8e8ff';ctx.beginPath();ctx.arc(s.x,s.y,s.r,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
ctx.strokeStyle='#7d94b510';ctx.lineWidth=1;for(let x=50;x<W;x+=50){ctx.beginPath();ctx.moveTo(x,55);ctx.lineTo(x,H);ctx.stroke()}for(let y=100;y<H;y+=50){ctx.beginPath();ctx.moveTo(20,y);ctx.lineTo(W-20,y);ctx.stroke()}
ctx.strokeStyle='#8ca1c533';ctx.lineWidth=2;ctx.strokeRect(20,54,W-40,H-74);ctx.strokeStyle='#68f2e122';ctx.setLineDash([5,12]);ctx.strokeRect(27,61,W-54,H-88);ctx.setLineDash([]);
// extraction gate
ctx.save();ctx.translate(gate.x,gate.y);ctx.rotate(elapsed*.35);ctx.strokeStyle=gate.open?'#68f2e1':'#46516a';ctx.lineWidth=3;ctx.shadowBlur=gate.open?25:0;ctx.shadowColor='#68f2e1';ctx.beginPath();ctx.arc(0,0,gate.r,0,Math.PI*2);ctx.stroke();ctx.rotate(-elapsed*.7);ctx.lineWidth=1;ctx.beginPath();ctx.arc(0,0,gate.r-9,0,Math.PI*2);ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle=gate.open?'#68f2e122':'#77829911';ctx.beginPath();ctx.arc(0,0,gate.r-10,0,Math.PI*2);ctx.fill();ctx.restore();
for(const c of cores){const pulse=1+Math.sin(elapsed*4+c.phase)*.18;ctx.save();ctx.translate(c.x,c.y);ctx.rotate(elapsed*.7+c.phase);ctx.shadowBlur=20;ctx.shadowColor='#68f2e1';ctx.fillStyle='#68f2e1';ctx.beginPath();ctx.moveTo(0,-c.r*pulse);ctx.lineTo(c.r*.72,0);ctx.lineTo(0,c.r*pulse);ctx.lineTo(-c.r*.72,0);ctx.closePath();ctx.fill();ctx.restore()}
for(const d of drones){ctx.save();ctx.translate(d.x,d.y);ctx.rotate(d.phase);ctx.shadowBlur=15;ctx.shadowColor='#ff5d9e';ctx.strokeStyle='#ff5d9e';ctx.fillStyle='#25132a';ctx.lineWidth=2;ctx.beginPath();for(let i=0;i<8;i++){const a=i*Math.PI/4,r=i%2?d.r*.68:d.r;ctx.lineTo(Math.cos(a)*r,Math.sin(a)*r)}ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#ffb0ca';ctx.beginPath();ctx.arc(0,0,3,0,Math.PI*2);ctx.fill();ctx.restore()}
for(const s of shots){ctx.shadowBlur=12;ctx.shadowColor='#68f2e1';ctx.fillStyle='#b8fff5';ctx.beginPath();ctx.arc(s.x,s.y,3.3,0,Math.PI*2);ctx.fill()}ctx.shadowBlur=0;
for(const s of enemyShots){ctx.fillStyle='#ff6c9e';ctx.shadowBlur=12;ctx.shadowColor='#ff5d9e';ctx.beginPath();ctx.arc(s.x,s.y,4,0,Math.PI*2);ctx.fill()}ctx.shadowBlur=0;
for(const p of particles){ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r*Math.max(.2,p.life/p.max),0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
if(player){ctx.save();ctx.translate(player.x,player.y);ctx.rotate(player.angle);if(player.invuln>0&&Math.floor(elapsed*14)%2)ctx.globalAlpha=.35;ctx.shadowBlur=player.dash>0?28:15;ctx.shadowColor='#68f2e1';ctx.fillStyle='#b7fff5';ctx.beginPath();ctx.moveTo(17,0);ctx.lineTo(-11,-9);ctx.lineTo(-7,0);ctx.lineTo(-11,9);ctx.closePath();ctx.fill();ctx.fillStyle='#68f2e1';ctx.beginPath();ctx.arc(-5,0,3,0,Math.PI*2);ctx.fill();if(player.dashLock>0){ctx.strokeStyle='#68f2e155';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,18,-Math.PI/2,-Math.PI/2+(1-player.dashLock/1.25)*Math.PI*2);ctx.stroke()}ctx.restore()}
ctx.restore()}
